    '81': DlogAlarmReference(machine: 'trima', code: '81', name: 'MSS PRIME TOO SOON RBC ALARM', statusLine: 'RBC additive solution prime error', messageType: 'R1', dlogText: 'Fluid too soon during RAS prime', category: '', alarmId: '', occursDuring: 'Metered Storage Solution Prime file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 80 of 292', detection: 'The return pump has processed at least 2 mL before the AC pump has processed at least 25 mL, and the MSS RBC prime delay alert did not occur while priming the RAS disposable set.', possibleCauses: 'l Defective Return Pump l Defective AC Pump l Defective I/O Two CCA l Defective Control CCA.', suggestedActions: 'Run pumps test in Autotest (service software).'),
    '82': DlogAlarmReference(machine: 'trima', code: '82', name: 'MSS PRIME TOO SOON PLT ALERT', statusLine: 'PAS prime error', messageType: 'R1', dlogText: 'Fluid too soon during PAS prime', category: '', alarmId: '', occursDuring: 'Metered Storage Solution Prime', detection: 'Reservoir status change seen before MSS prime return limit pumped. Return pump processed 2 mL or more from the reservoir before the plasma pump pulled 13 mL from the storage solution bag.', possibleCauses: 'l Channel clamps not closed. l Additive solution connected too soon. l Defective lower level sensor. l Defective return pump. l Return pump occlusion error. l Defective Ultrasonic CCA. l Defective Safety CCA.', suggestedActions: 'Verify the lower level reservoir sensor is functioning correctly. Load'),
