    '138': DlogAlarmReference(machine: 'trima', code: '138', name: 'SET IDENTIFICATION ALARM', statusLine: 'Unable to identify tubing set type', messageType: 'OPERATOR ATTENTION', dlogText: 'Prompt operator to manually determine the set type', category: '', alarmId: '', occursDuring: 'Disposable Test', detection: 'Using the RBC detector, the machine is not able to determine which type of disposable set is loaded because the reading is between the white stamp criteria and the black stamp criteria.', possibleCauses: 'l RBC detector is miscalibrated. l RBC detector is misaligned. l RBC detector is dirty. l RBC detector is defective. l Tubing set not loaded properly. l Tubing set cassette scratched or dirty behind stamp. l Defective Control Computer.', suggestedActions: 'l Calibrate the RBC detector.'),
