    '141': DlogAlarmReference(machine: 'trima', code: '141', name: 'TEN MINUTE PAUSE', statusLine: 'Ten minute pause', messageType: 'R1', dlogText: 'Pumps Paused 10 Minutes', category: '', alarmId: '', occursDuring: 'Blood Prime - Metered Storage Solution Addition', detection: 'The pumps have been paused for 10 minutes during a return cycle, or the pumps were paused for 10 minutes during a draw cycle but the operator was able to perform the Access Keep Open during the 3 minute pause alert.', possibleCauses: 'l Donor has an access problem that results in an extended pause condition. l Operator pressed the pause key. l Defective I/O One CCA file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 133 of 292', suggestedActions: 'None'),
