    '143': DlogAlarmReference(machine: 'trima', code: '143', name: 'TOO MANY RESERVOIR DRAW ALARMS', statusLine: 'Level sensor failure', messageType: 'A1', dlogText: 'Too many consecutive reservoir draw alarms', category: '', alarmId: '', occursDuring: 'Blood Prime - Blood Run', detection: '3 or more consecutive Level Sensor Error alerts have occurred in a row, or 6 Level Sensor Errors have occurred throughout all draw cycles.', possibleCauses: 'l Defective upper-level reservoir sensor. l Defective Ultrasonic CCA. l Defective I/O Two CCA l Defective Safety CCA. l Defective Control CCA. l Defective Inlet pump or Inlet pump rotor occlusion. l Valves are not properly occluding.', suggestedActions: 'l Verify the upper level reservoir sensor is functioning correctly.'),
    '144': DlogAlarmReference(machine: 'trima', code: '144', name: 'TOO MANY RESERVOIR RETURN ALARMS', statusLine: 'Level sensor error', messageType: 'A1', dlogText: 'Too many consecutive reservoir return alarms', category: '', alarmId: '', occursDuring: 'Blood Prime - Blood Run', detection: '2 or more consecutive Level Sensor Error alerts have occurred in a row, or 6 Level Sensor Errors have occurred throughout all return cycles.', possibleCauses: 'l Defective lower reservoir level sensor, l Defective Ultrasonic CCA. l Defective I/O Two CCA l Defective Safety CCA. l Defective Control CCA. l Defective Inlet pump or Inlet pump rotor occlusion. l Valves are not properly occluding.', suggestedActions: 'l Verify the lower level reservoir sensor is functioning correctly.'),
    '145': DlogAlarmReference(machine: 'trima', code: '145', name: 'RESERVOIR FULL AFTER RETURN', statusLine: 'Level sensor failure', messageType: 'A1', dlogText: 'Reservoir full after return cycle', category: '', alarmId: '', occursDuring: 'Blood Run', detection: 'The upper level sensor detects fluid after the return pump processed 65 mL.', possibleCauses: 'l Defective upper-level reservoir sensor. l Defective Ultrasonic CCA. l Defective I/O Two CCA l Defective Safety CCA. l Defective Control CCA.', suggestedActions: 'l Verify the upper level reservoir sensor is functioning correctly.'),
    '146': DlogAlarmReference(machine: 'trima', code: '146', name: 'UNLOADING BAD CASSETTE POSITION', statusLine: 'Cassette unload error', messageType: 'R1', dlogText: 'UNLOADING Bad Cassette Position', category: '', alarmId: '', occursDuring: 'Donor Disconnect', detection: 'The cassette was sensed to be neither up nor down by the optical sensors.', possibleCauses: 'l Cassette was in the middle of either loading or unloading when the Trima shut down. l Operator partially unloaded the cassette manually. l Defective cassette optical sensors. l Defective linear actuator. l Defective Valve Driver CCA. l Defective I/O One CCA l Defective Control CCA.', suggestedActions: 'l Verify there are no obstructions between the cassette plate and'),
    '147': DlogAlarmReference(machine: 'trima', code: '147', name: 'VALVE HARDWARE FAILURE file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 138 of 292', statusLine: 'Valve error', messageType: 'R1', dlogText: 'Valve hardware Failure', category: '', alarmId: '', occursDuring: 'Startup Tests - Metered Storage Solution Addition', detection: 'A valve is sensed to have an over current condition as sensed by the valve driver CCA.', possibleCauses: 'l Mechanical obstruction preventing the valve from going to commanded position. l Defective valve assembly. l Defective Valve Driver CCA. l Defective I/O One CCA l Defective Control CCA. l Loose connector or shorted wire.', suggestedActions: 'l Run the Valves and Cassette test and Voltage test in Autotest.'),
    '148': DlogAlarmReference(machine: 'trima', code: '148', name: 'VALVE TEST FAILURE', statusLine: 'Valve error', messageType: 'R1', dlogText: 'Valve test Failure', category: '', alarmId: '', occursDuring: 'Startup Tests', detection: 'During the Startup Tests, all three valves are moved to all three positions. If any valve cannot achieve any of its positions before the time-out, this alert is generated.', possibleCauses: 'l Valve is mechanically obstructed. l Defective valve assembly. l Defective Valve Driver CCA. l Defective I/O One CCA l Defective Control CCA.', suggestedActions: 'l Run the Valves and Cassette test and Voltage test in Autotest.'),
    '149': DlogAlarmReference(machine: 'trima', code: '149', name: 'HEMOLYSIS DETECTED ALARM', statusLine: 'Blood prime failure', messageType: 'A1', dlogText: 'Hemolysis detected', category: '', alarmId: '', occursDuring: 'Blood Prime - Blood Run', detection: 'An RBC detector R/G ratio of greater than or equal to 50 is seen during the first draw. Then during first return the R/G ratio is greater than 1.1 and the green reflectance is less than 1000 and the centrifuge is commanded to 200 or greater. file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 140 of 292', possibleCauses: 'l RBC detector is miscalibrated. l RBC detector is misaligned. l RBC detector is dirty. l RBC detector is defective. l Tubing set not loaded properly. l Defective Control Computer.', suggestedActions: 'l Calibrate the RBC detector.'),
    '150': DlogAlarmReference(machine: 'trima', code: '150', name: 'GENERIC PLT WBC CONTAMINATION ALERT', statusLine: 'Potential WBC contamination detected', messageType: 'R1', dlogText: 'Inform operator about possible plt wbc contamination', category: '', alarmId: '', occursDuring: 'Blood Run', detection: 'The machine has detected that the platelet product may have WBC contamination and should be flagged.', possibleCauses: 'Suggested Actions', suggestedActions: 'Parent topic: 7.0 Alarms Trima Accel Automated Blood Collection System Generation 2 | Service Manual'),
    '151': DlogAlarmReference(machine: 'trima', code: '151', name: 'AC CLOSURE FAILED CONTINUE PAS ALARM', statusLine: 'AC disconnect failure', messageType: 'R1', dlogText: 'AC Closure Failed Alarm (RAS disabled. PAS allowed to continue)', category: '', alarmId: '', occursDuring: 'Metered Storage Solution Addition', detection: 'The AC closure failed alert has been triggered 3 times. RAS addition will not occur, but PAS addition can still be performed.', possibleCauses: 'Suggested Actions', suggestedActions: 'Parent topic: 7.0 Alarms Trima Accel Automated Blood Collection System Generation 2 | Service Manual'),
    '153': DlogAlarmReference(machine: 'trima', code: '153', name: 'CONTROL PRE WATCHDOG PAUSE', statusLine: 'NA', messageType: 'R1', dlogText: 'Pre Watchdog pause', category: '', alarmId: '', occursDuring: 'Any substate', detection: 'Ethernet communication delay between safety and control after 2 seconds. Pauses pumps and alerts operator on status bar for 6 seconds and waits for system to re-establish communication. May recover within the 8 second window.', possibleCauses: 'l High latency between control and safety. l Software or hardware is calculating or processing information that delays the response of control or safety. l Poor ethernet cable connection or TCP/IP communication between safety and control. l Bad sector on hard drive.', suggestedActions: 'l Run TINT test.'),
    '154': DlogAlarmReference(machine: 'trima', code: '154', name: 'EVACUATION PRESSURE ALERT JP', statusLine: 'Pressure test error', messageType: 'R1', dlogText: 'Pressure detected during bag evacuation (japanese bmp)', category: '', alarmId: '', occursDuring: 'Evacuate Bag substate', detection: 'After cassette is loaded, if the APS pressure exceeds 25 mmHg a warning alarm is triggered. If this occurs a second time, donor disconnect occurs.', possibleCauses: 'l Needle line clamp is clamped or obstructed during air removal. l Miscalibrated APS. l Defective APS. l Defective APS/CPS Adapter CCA. l Defective I/O Two CCA l Defective Control CCA.', suggestedActions: 'l Unclamp donor line.'),
    '155': DlogAlarmReference(machine: 'trima', code: '155', name: 'APS AUTO ZERO FILE ERROR', statusLine: 'System test failure', messageType: 'A1', dlogText: 'APS file operation error', category: '', alarmId: '', occursDuring: 'Self Tests', detection: 'During the boot, the Control computer attempts to check the integrity of the file structure. If the file is corrupt this alarm is generated. file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 144 of 292', possibleCauses: 'Defective Control Computer.', suggestedActions: 'l Reload software'),
    '156': DlogAlarmReference(machine: 'trima', code: '156', name: 'MOTOR INTEGRATION ERROR', statusLine: 'Motor hardware failure', messageType: 'R1', dlogText: 'Motor Integration error', category: '', alarmId: '', occursDuring: 'Any substate', detection: 'Pump motor optical encoder speed (actual speed) could not reach or maintain the commanded speed within the limits of the software control loop. This is one of three variables in computing a pump speed error over 40- 45 samples (approx 0.4 seconds). Alarms 90 and 157 are also used and could be a trigger. Primary trigger component: The accumulated error (integration of speed curve) of the difference between the commanded speed and actual speed was too great over 40-45 samples (approx 0.4 seconds).', possibleCauses: 'l Defective pump motor. l Defective pump rotor. file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 145 of 292 l Misloaded pump header. l Misaligned pump raceway. l Defective I/O Two CCA l Defective Pump Driver CCA l Defective I/O One CCA l Defective Control CCA.', suggestedActions: 'l Run pumps test in Autotest (service software).'),
    '157': DlogAlarmReference(machine: 'trima', code: '157', name: 'MOTOR VOLUME ERROR', statusLine: 'Motor hardware failure', messageType: 'R1', dlogText: 'Motor Volume Error', category: '', alarmId: '', occursDuring: 'Any substate', detection: 'Pump motor optical encoder speed (actual speed) could not reach or maintain the commanded speed within the limits of the software control loop. This is one of three variables in computing a pump speed error over 40- file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 146 of 292 45 samples (approx 0.4 seconds). Alarms 90 and 156 are also used and could be a trigger. Primary trigger component: The accumulated error of the difference between expected encoder counts and actual encoder counts was too great over 40-45 samples (approx 0.4 seconds).', possibleCauses: 'l Defective pump motor. l Defective pump rotor. l Misloaded pump header. l Misaligned pump raceway. l Defective I/O Two CCA l Defective Pump Driver CCA l Defective I/O One CCA l Defective Control CCA.', suggestedActions: 'l Run pumps test in Autotest (service software).'),
    '158': DlogAlarmReference(machine: 'trima', code: '158', name: 'MOTOR DISABLED', statusLine: 'Motor hardware failure', messageType: 'R1', dlogText: 'Motor Disabled', category: '', alarmId: '', occursDuring: 'Any substate', detection: 'Pump fault from motor driver CCA was detected.', possibleCauses: 'l Over-current or under voltage was detected on the motor driver CCA which generated the pump fault. l Pump rotor or pump shaft physically stopped by something. l Pump motor problem: Binding, shorting, open winding, etc. l Defective I/O Two CCA l Defective Pump Driver CCA l Defective I/O One CCA l Defective Control CCA.', suggestedActions: 'l Check for debris that could bind the pump.'),
    '162': DlogAlarmReference(machine: 'trima', code: '162', name: 'FAILURE TO PRESSURIZE INLET FINAL', statusLine: 'Pressure test error', messageType: 'A1', dlogText: 'Pressure Test Failure Ending Run', category: '', alarmId: '', occursDuring: 'Sample bag check file:///C:/Users/cmararb/AppData/Local/Temp/~hhFFBB.htm 9/26/2026 7.0 Alarms Page 148 of 292', detection: 'After the first failure to pressurize inlet, this pressure test is run. After 15 ml of return pump volume, the APS pressure did not reach 51 mmHg. If this test does not pass, donor disconnect occurs.', possibleCauses: 'l Access line clamp or sample bag clamp not closed. l Cassette not fully loaded. l Valves not occluding properly. l Leak in tubing set. l Defective APS. l AC, inlet, or return pump not occluding properly. l AC, inlet, or return pump defective. l Defective APS/CPS adapter CCA. l Defective I/O Two CCA l Defective Control CCA.', suggestedActions: 'l Close access line or sample bag clamp.'),
    '163': DlogAlarmReference(machine: 'trima', code: '163', name: 'AUTOFLOW TIME ALERT', statusLine: 'Donation time increase', messageType: 'R1', dlogText: 'Inform operator proc time increased 10 mins due to autoflow', category: '', alarmId: '', occursDuring: 'Blood Run state', detection: 'The system monitors the predicted procedure time, and generates this alert if AutoFlow adjustments cause the current procedure time to exceed the baseline procedure time by more than 10 minutes, only including procedure time changes due to AutoFlow adjustments.', possibleCauses: 'The AutoFlow 10 minute increase advisory when AutoFlow adjustments cause the AutoFlow procedure time delta to increase by >= 10 minutes.', suggestedActions: 'Normal response, no action required.'),
