  static const Map<String, DlogAlarmReference> reveosByCode = {
    '2402': DlogAlarmReference(machine: 'reveos', code: '2402', name: 'Stop button problem', statusLine: '', messageType: '', dlogText: '', category: 'Safety', alarmId: 'StopSwitchDiscrepancyAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the control computer and safety computer do not agree that the stop button was pressed.', possibleCauses: 'The stop button or its connections are defective. Check the stop button for proper operation and connections. The e-box or its connections are defective. Check the e-box for proper operations and connections. Replace it if it is defective. Power cycle to clear the alarm.', suggestedActions: ''),
    '2600': DlogAlarmReference(machine: 'reveos', code: '2600', name: 'Communication problem--Obsolete', statusLine: '', messageType: '', dlogText: '', category: 'Safety', alarmId: 'SafetyCommunicationFault', occursDuring: 'This alarm is not used.', detection: 'This alarm is raised when the control computer cannot communicate with the safety computer.', possibleCauses: 'The ethernet connector CCA is defective. Power cycle to clear the alarm. The ethernet cable between the ethernet switch and the e-box is loose.', suggestedActions: ''),
    '1000': DlogAlarmReference(machine: 'reveos', code: '1000', name: 'Data transfer', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'FTPFailureAlert', occursDuring: 'At the end of the procedure.', detection: 'This alarm is raised when the log files did not successfully upload from the Reveos device to the data system manager.', possibleCauses: 'The Reveos device is not connected to the data system manager. Confirm that the data system manager and the associated network are connected then reset all the components. The Reveos device was de-energized after a completed blood protocol but before the device completed the next procedure transition. Do not de-energize the Reveos device at the end of a blood protocol until the device has finished the next procedure transition. The ethernet port on the device is defective. Connect to the affected ethernet port on the Reveos device using STS. The ethernet switch is defective or it has a loose connection. Replace the e-box.', suggestedActions: ''),
    '1001': DlogAlarmReference(machine: 'reveos', code: '1001', name: 'Potential data loss', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'FTPAndArchiveFailureAlert', occursDuring: 'At the end of the procedure.', detection: 'This alarm is raised when the device has more than 250 files that have not been transferred to the data system manager.', possibleCauses: 'The compact flash card has reached the maximum limit for log files and did not transfer files to the data system manager. Manually transfer log files to the data system manager. The Reveos device is not connected to the data system manager. Reestablish connection to the data system manager. to allow the Reveos device to transfer log files. The ethernet port on the device is defective. Connect to the affected ethernet port on the Reveos device using STS. The ethernet switch is defective or there is a loose connection. Replace the e-box.', suggestedActions: ''),
    '1016': DlogAlarmReference(machine: 'reveos', code: '1016', name: 'Invalid operator ID', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'BarcodeInvalidOperatorAlert', occursDuring: 'Operator ID (barcode) entry.', detection: 'This alarm is raised when the system did not accept the barcode scanned for the operator ID.', possibleCauses: 'An incorrect barcode was scanned. Scan the correct operator barcode. Barcoding in the data system manager is not properly configured. Correctly configure the operator ID barcodes in the data system manager.', suggestedActions: ''),
    '1018': DlogAlarmReference(machine: 'reveos', code: '1018', name: 'Data lost', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'PersistDataFailureAlert', occursDuring: 'At beginning of the procedure.', detection: 'This alarm is raised when the protocol persistent data cannot be saved at the end of a run or retrieved at the beginning of a run.', possibleCauses: 'The Reveos device is not connected to the data system manager. Confirm that the data system manager and the associated network are connected, then reset all the components. The Reveos device has a software issue. Reboot the Reveos device. The ethernet port on the device is defective. Connect to the affected ethernet port on the Reveos device using STS. The ethernet switch is defective or there is a loose connection. Replace the ethernet switch.', suggestedActions: ''),
    '1019': DlogAlarmReference(machine: 'reveos', code: '1019', name: 'Connectivity problem', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'ConfigFailureAlert', occursDuring: 'Always active.', detection: 'This alarm is raised when the device fails to download the configuration and protocol from the data system manager.', possibleCauses: 'The configuration file on the device does not exist in the data system manager. Download a valid configuration from the data system manager. The Reveos device is not connected to the data system manager. Confirm that the data system manager and the associated network are connected, then reset all the components. The ethernet port on the device is defective. Connect to the affected ethernet port on the Reveos device using STS. The compact flash card is defective. Replace the compact flash card. The ethernet switch is defective or there is a loose connection. Replace the e-box.', suggestedActions: ''),
    '1020': DlogAlarmReference(machine: 'reveos', code: '1020', name: 'Invalid scans', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket1BarcodesInDisabledBucketAlert', occursDuring: 'Barcode scanning.', detection: 'This alarm is raised when a whole blood bag is scanned for a disabled bucket.', possibleCauses: 'A counterbalance bag must be scanned and loaded in that bucket. Scan and load a counterbalance bag for this bucket. The bucket is disabled due to a failure associated with that bucket/quadrant. Identify the failure associated with that bucket/quadrant then repair the device to re-enable that bucket.', suggestedActions: ''),
    '1021': DlogAlarmReference(machine: 'reveos', code: '1021', name: 'Invalid scans', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket2BarcodesInDisabledBucketAlert', occursDuring: 'Barcode scanning.', detection: 'This alarm is raised when a whole blood bag is scanned for a disabled bucket.', possibleCauses: 'A counterbalance bag must be scanned and loaded in that bucket. Scan and load a counterbalance bag for that bucket. The bucket is disabled due to a failure associated with that bucket/quadrant. Identify the failure associated with that bucket/quadrant then repair the device to re-enable that bucket.', suggestedActions: ''),
    '1022': DlogAlarmReference(machine: 'reveos', code: '1022', name: 'Invalid scans', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket3BarcodesInDisabledBucketAlert', occursDuring: 'Barcode scanning.', detection: 'This alarm is raised when a whole blood bag is scanned for a disabled bucket.', possibleCauses: 'A counterbalance bag must be scanned and loaded in that bucket. Scan and load a counterbalance bag for that bucket. The bucket is disabled due to a failure associated with that bucket/quadrant. Identify the failure associated with that bucket/quadrant then repair the device to re-enable that bucket.', suggestedActions: ''),
    '1023': DlogAlarmReference(machine: 'reveos', code: '1023', name: 'Invalid scans', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket4BarcodesInDisabledBucketAlert', occursDuring: 'Barcode scanning.', detection: 'This alarm is raised when a whole blood bag is scanned for a disabled bucket.', possibleCauses: 'A counterbalance bag must be scanned and loaded in that bucket. Scan and load a counterbalance bag for that bucket. The bucket is disabled due to a failure associated with that bucket/quadrant. Identify the failure associated with that bucket/quadrant, then repair the device to re-enable that bucket.', suggestedActions: ''),
    '1024': DlogAlarmReference(machine: 'reveos', code: '1024', name: 'Invalid manual entry', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'BarcodeManualEntryMismatchAlert', occursDuring: 'Manual barcode entry.', detection: 'This alarm is raised when the barcode number manually entered by the operator does not match the confirmation.', possibleCauses: 'One of the two manual barcode number entries is wrong. Check the manual barcode entry. The touchscreen needs to be calibrated. Recalibrate the touchscreen.', suggestedActions: ''),
    '1026': DlogAlarmReference(machine: 'reveos', code: '1026', name: 'Problem sealing', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket1PlateletValveLongSealFailureAlert', occursDuring: 'Valve sealing.', detection: 'This alarm is raised when the weld time exceeded 6 seconds.', possibleCauses: 'The component valve sealing surfaces are dirty. Clean the component valve anvils using the procedure from the operator\'s manual. The tubing is incorrect, the tubing is the incorrect temperature, or the tubing has moisture. Use only Reveos tubing that is clean, dry, and at room temperature. The tubing was misloaded under the component valve. Verify that the tubing is properly loaded under the component valve anvils. The RF welding circuit is defective or there is a loose connection. Troubleshoot the RF welding and control circuits using the e-rotor block diagram. The connection between the RF power supply and the e-box is defective. Replace any defective connections. The e-rotor is defective or there is a loose connection. Determine whether the problem affects just one valve or all the valves. If the problem is only with one valve, troubleshoot the e-rotor. If the problem affects all valves, troubleshoot the components that are external to the e-rotor. The slip ring is defective. Test the slip ring in different positions to check for proper brush contact. The system power supply voltages are out of range. Confirm that the system power supply voltages are in range under load. An e-rotor component may have failed. To determine the occurrence rate of failure, perform a RAT search on the log files; set the search parameters for one month at minimum. Longer is preferable. Replace the e-rotor only when the problem becomes frequent.', suggestedActions: ''),
