    '1050': DlogAlarmReference(machine: 'reveos', code: '1050', name: 'Basin temperature too high', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'BasinOverTempFailureAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the output value of the basin temperature sensor exceeds the maximum limit of 27 °C.', possibleCauses: 'There is a problem with the chiller system, the centrifuge bearing, or another component that is generating excessive heat inside the device. Check the chiller system for proper operation. The basin temperature sensor is defective. Verify that the basin temperature sensor is accurately measuring the basin temperature. The device\'s operating environment is too hot. Determine whether the air temperature outside of the device is out of specification. The bearing temperature sensor is defective. Determine whether the centrifuge bearing temperature operates correctly when the centrifuge is spinning. Replace if defective.', suggestedActions: ''),
    '1051': DlogAlarmReference(machine: 'reveos', code: '1051', name: 'Basin temperature too low', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'BasinUnderTempFailureAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the output value of the basin temperature sensor exceeds the minimum limit of 17 °C.', possibleCauses: 'The device\'s operating environment is too cold. Determine whether the device\'s operating environment for temperature is out of specification. The basin temperature sensor is defective. Verify the basin temperature sensor is accurately measuring the actual basin temperature. A component in the chiller system is defective. Check the chiller system for proper operation.', suggestedActions: ''),
    '1052': DlogAlarmReference(machine: 'reveos', code: '1052', name: 'Bag mismatch', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket1DummyAlert', occursDuring: 'Barcode scanning.', detection: 'This alarm is raised when the output of the line sensor indicates a counterbalance bag is loaded in the bucket when a whole blood bag was scanned.', possibleCauses: 'The bucket has a counterbalance bag when a whole blood bag was scanned. Unload any counterbalance bags and load the correct whole blood bag. The line sensor is dirty. Clean the line sensors. The line sensor calibration values in cal.dat are corrupt. Force a line sensor calibration by changing the line sensor values to zero in cal.dat. The line sensor or the e-rotor cable is defective. Check the line sensor output. If it is out of range, replace the e-rotor.', suggestedActions: ''),
