    '1060': DlogAlarmReference(machine: 'reveos', code: '1060', name: 'Communication problem', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'ICDUnexpectedErrorReceivedAlert', occursDuring: 'When selecting protocol.', detection: 'This alarm is raised when a timeout occurs during the downloading of a procedure to the device.', possibleCauses: 'The procedure is corrupt. Download the procedure again. There is a timing error. Cycle the power to clear the alarm.', suggestedActions: ''),
    '1061': DlogAlarmReference(machine: 'reveos', code: '1061', name: 'Empty bucket detected', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket1EmptyAlert', occursDuring: 'Barcode scanning.', detection: 'This alarm is raised when the output of the line sensor indicates the bucket is empty when the operator scanned a whole blood bag or counterbalance bag.', possibleCauses: 'The bucket is empty when either a whole blood bag or a counterbalance bag must be loaded. Confirm the barcode reader is scanning correctly, and load either the correct whole blood bag or a counterbalance bag. The line sensor calibration values in cal.dat are corrupt. Force a line sensor calibration by changing the line sensor values to zero in cal.dat. The line sensor or the e-rotor cable is defective. Check the line sensor output. If it is out of range, replace the e-rotor. The line sensor is dirty. Clean the line sensors.', suggestedActions: ''),
