    '1064': DlogAlarmReference(machine: 'reveos', code: '1064', name: 'Empty bucket detected', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket4EmptyAlert', occursDuring: 'Barcode scanning.', detection: 'This alarm is raised when the output of the line sensor indicates the bucket is empty when the operator scanned a whole blood bag or counterbalance bag.', possibleCauses: 'The bucket is empty when either a whole blood bag or a counterbalance bag must be loaded. Confirm that the barcode reader is scanning correctly, and load either the correct whole blood bag or a counterbalance bag. The line sensor calibration values in cal.dat are corrupt. Force a line sensor calibration by changing the line sensor values to zero in cal.dat. The line sensor or the e-rotor cable is defective. Check the line sensor output. If it is out of range, replace the e-rotor. The line sensor is dirty. Clean the line sensors.', suggestedActions: ''),
    '1065': DlogAlarmReference(machine: 'reveos', code: '1065', name: 'Empty bucket not detected', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket1NotEmptyAlert', occursDuring: 'Before barcode scanning.', detection: 'This alarm is raised when the output of the line sensor indicates the bucket has a whole blood bag or a counterbalance bag when it must be empty.', possibleCauses: 'A bucket that must be empty has a counterbalance bag or whole blood bag loaded in it. Unload the bucket, remove the tubing from the line sensor, and then clear the alarm. The buckets were loaded during the startup state. Ensure nothing is loaded in the buckets or the line sensors during the startup state.. Do not begin loading until the barcode scan screen appears. The line sensor is dirty. Clean the line sensors. The line sensor calibration values in cal.dat are corrupt. Force a line sensor calibration by zeroing line sensor values in cal.dat. The line sensor or the e-rotor cable is defective. Check the line sensor output. If it is out of range, replace the e-rotor.', suggestedActions: ''),
    '1066': DlogAlarmReference(machine: 'reveos', code: '1066', name: 'Empty bucket not detected', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket2NotEmptyAlert', occursDuring: 'Before barcode scanning.', detection: 'This alarm is raised when the output of the line sensor indicates the bucket has a whole blood bag or a counterbalance bag when it must be empty.', possibleCauses: 'A bucket that must be empty has a counterbalance bag or whole blood bag loaded in it. Unload the bucket, remove the tubing from the line sensor, and then clear the alarm. The buckets were loaded during the startup state. Ensure nothing is loaded in the buckets or the line sensors during the startup state. Do not begin loading until the barcode scan screen appears. The line sensor is dirty. Clean the line sensors. The line sensor calibration values in cal.dat are corrupt. Force a line sensor calibration by zeroing line sensor values in cal.dat. The line sensor or the e-rotor cable is defective. Check the line sensor output. If it is out of range, replace the e-rotor.', suggestedActions: ''),
