    '1069': DlogAlarmReference(machine: 'reveos', code: '1069', name: 'Leak detected', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'LeakDetectedAlert', occursDuring: 'Startup, Load, and Unload when the outer lid is open.', detection: 'This alarm is raised when the leak detector output voltage indicates a leak.', possibleCauses: 'Fluid or an object passed in front of the leak detector. Confirm there is nothing in the basin that could trigger the leak detector, and confirm the leak detector is calibrated correctly. There is fluid on the leak detector. Clean the basin and the leak detector then verify that both are dry. The leak detector is not calibrated correctly. Recalibrate the leak detector. The leak detector failed. Replace the leak detector. The leak detector amplifier failed. Replace the leak detector amplifier.', suggestedActions: ''),
    '1070': DlogAlarmReference(machine: 'reveos', code: '1070', name: 'Hydraulic pressure problem', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'HydraulicsAmbientCalibrationOutOfRange', occursDuring: 'Startup', detection: 'This alarm is raised when the startup hydraulic ambient pressure calibration is less than 0.75 bar (or 0.65 bar for high altitude sites) or greater than 1.15 bar.', possibleCauses: 'An alarm during the startup state forced a hydraulic reset to take place. The hydraulic reset did not complete before the ambient pressure calculation started. The reset takes priority and can cause the system to calibrate from a false value. Continue past the alert. The device will use the ambient pressure calibration value that is stored in cal.dat. The hydraulic pressure or the volume of the hydraulic fluid sent to the rotor was too high when the device was powered down. Reboot the device to force a recalibration. The pump motor is defective. Replace the linear guide. The hydraulic system is leaking, the hydraulic pressure sensor has failed, or there is a communication failure. If the problem happens consistently, troubleshoot the hydraulic system. The ambient pressure calibration range is set too high for the altitude the device is operating at. Check the ambient pressure calibration value in cal.dat. The lower limit must be set to 0.65 bar for devices at altitudes of 2001 to 3000 meters.', suggestedActions: ''),
    '1073': DlogAlarmReference(machine: 'reveos', code: '1073', name: 'Bucket disabled', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'PreRunBucket1DisabledAlert', occursDuring: 'Load Disposable', detection: 'This alarm is raised when a bucket was disabled prior to the run starting.', possibleCauses: 'Prior to the beginning of a run, the bucket is disabled due to a failure associated with that bucket/quadrant. Identify the failure associated with that bucket/quadrant then repair the device to re-enable that bucket. A counterbalance bag must be scanned and loaded in that bucket. Scan and load a counterbalance bag for this bucket.', suggestedActions: ''),
