    '1077': DlogAlarmReference(machine: 'reveos', code: '1077', name: 'Duplicate donation ID', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'DuplicateDonationIdBucket1Alert', occursDuring: 'Load Disposable', detection: 'This alarm is raised when the operator scans a donation ID that has already been assigned to a different bucket, if duplicate donation IDs are not allowed in the the data system manager configuration.', possibleCauses: 'Operator error. Check the prior buckets for correct loading and scanning. Scan and load a different product. The data system manager is not configured properly. Configure the data system manager correctly.', suggestedActions: ''),
