    '1081': DlogAlarmReference(machine: 'reveos', code: '1081', name: 'Plasma detection problem', statusLine: '', messageType: '', dlogText: '', category: 'Alerts', alarmId: 'Bucket1LipemicAlert', occursDuring: 'Plasma Expression', detection: 'This alarm is raised when the line sensor cannot detect the plasma interface. The line sensor must detect a 10% rise in either the red or blue transmitted values after the Reveos has pumped 100 mL of fluid.', possibleCauses: 'The component bag set was loaded incorrectly. Correctly load the tubing. The plasma is lipemic. Check for lipemic plasma. The line sensor is dirty. Clean the line sensor and confirm it is operating correctly.', suggestedActions: ''),
