    '1100': DlogAlarmReference(machine: 'reveos', code: '1100', name: 'Centrifuge voltage--Obsolete', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugeVoltageAlarm', occursDuring: 'This alarm is not used.', detection: 'This alarm is raised when the +24 V DC power into the centrifuge motor controller is less than +18 V DC or greater than +30 V DC.', possibleCauses: 'The +24 V DC supply to centrifuge motor controller is missing or out of range. Check the connection between the DC interconnect CCA and the centrifuge motor controller. Remove the +24 V DC connector to verify that it is not being loaded down by the centrifuge motor controller. The centrifuge motor controller is defective. Replace the centrifuge motor controller', suggestedActions: ''),
    '1101': DlogAlarmReference(machine: 'reveos', code: '1101', name: 'Centrifuge system', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugeHardwareAlarm', occursDuring: 'While centrifuge is running.', detection: 'This alarm is raised when the centrifuge motor controller resolver detects incorrect rotation.', possibleCauses: 'The centrifuge motor controller is defective. Replace the centrifuge motor controller. The centrifuge motor is defective. Replace the centrifuge motor. The centrifuge motor controller has not been commissioned or programmed correctly. Check the CMC operation and commissioning/programming. The connections between the centrifuge motor controller and the motor are defective. Check the connections between the CMC and the motor.', suggestedActions: ''),
    '1102': DlogAlarmReference(machine: 'reveos', code: '1102', name: 'Centrifuge command', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugeCommandFailureAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the control computer receives an invalid CMC command.', possibleCauses: 'The Reveos device has a software issue due to either timing or incompatible versions between the device software and STS, the protocol, or the CMC. Check the compatibility of software upgrades or downgrades. Expect this alarm until the upgrades or downgrades are complete. Reload the software with a known version, such as a released CD from a spares kit, and upload files from the usb drive stored with the device. The compact flash card is defective. Replace the compact flash card. The control computer is defective or there is a loose connection. Check the control computer for proper operation and connections. The system power supply voltages are out of range. Confirm the system power supply voltages are in range under load. An e-rotor component may have failed. To determine the occurrence rate of failure, perform a RAT search on the log files; set the search parameters for one month at minimum. Longer is preferable. Replace the e-rotor only when the problem becomes frequent.', suggestedActions: ''),
    '1103': DlogAlarmReference(machine: 'reveos', code: '1103', name: 'Centrifuge speed too high', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugeOverspeedAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the centrifuge motor controller detects that the centrifuge speed exceeded 3300 rpm. The control computer generates this alarm.', possibleCauses: 'The centrifuge motor controller is defective. Replace the centrifuge motor controller The centrifuge motor controller has not been commissioned or programmed correctly. Check the CMC operation and commissioning/programming.', suggestedActions: ''),
    '1104': DlogAlarmReference(machine: 'reveos', code: '1104', name: 'Centrifuge speed', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugeSpeedToleranceAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the control computer detects that the commanded and actual speeds of the centrifuge differ by more than 50 rpm.', possibleCauses: 'The centrifuge motor controller is defective. Replace the centrifuge motor controller. The connections between the centrifuge motor controller and the motor are defective. Check the CMC connections. The AC input to the centrifuge motor controller is out of range. Check the AC input voltage to CMC. The centrifuge motor controller has not been commissioned or programmed correctly. Check the CMC operation and commissioning/programming.', suggestedActions: ''),
    '1105': DlogAlarmReference(machine: 'reveos', code: '1105', name: 'Centrifuge hardware', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugeBeltBrokenAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the centrifuge speeds reported by the centrifuge motor resolver and the rotation sensor differ by more than 50 rpm.', possibleCauses: 'There is a problem with the centrifuge drive belt. Check the centrifuge belt. The rotation sensor is defective or the gap between the sensor and the speed ring is out of range. Check the rotation sensor and verify that the gap between the sensor and the speed ring is between 1 mm and 1.5 mm. The centrifuge motor controller is defective. Check the CMC operation and commissioning/programming. The centrifuge motor or its slipping pulley is defective. Check the centrifuge motor for slipping pulley and proper operation. The AC input to the centrifuge motor controller is out of range. Check the AC input to the centrifuge motor controller.', suggestedActions: ''),
    '1106': DlogAlarmReference(machine: 'reveos', code: '1106', name: 'Centrifuge power', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugePowerCommandMismatchAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the safety system changed the CMC relay status to either on or off, and the AC monitor CCA did not report the change in voltage. Power status: On is line voltage greater than 90 V AC. Off is line voltage less than 90 V AC. The AC is converted to a DC output by the AC monitor CCA. 90 AC is about 2.6 DC. 230 AC is about 7.9 DC.', possibleCauses: 'The AC line voltage is low. Check the centrifuge power status using STS to confirm that the safety system the correct command. The AC monitor CCA or its connections are defective. Replace the AC monitor CCA. The CMC relay is defective or there is a loose connection. Replace the CMC relay. The interface CCA or its connections are defective. Replace the e-box. The control CCA is defective. Replace the e-box. The safety CCA is defective. Replace the e-box.', suggestedActions: ''),
    '1107': DlogAlarmReference(machine: 'reveos', code: '1107', name: 'Centrifuge system', statusLine: '', messageType: '', dlogText: '', category: 'Centrifuge', alarmId: 'CentrifugeSlowSpeedRangeAlarm', occursDuring: 'Startup', detection: 'This alarm is raised when the speed selected in cal.dat for the low speed vibration check is less than 160 rpm or greater than 200 rpm.', possibleCauses: 'The value stored in w_cal.dat file is incorrect. Use STS to change the cal.dat "SpeedCutoff" to 185 rpm. One of the files is corrupt. Use STS to return to a known good w_cal.dat file. The compact flash card has malfunctioned. Replace the compact flash card.', suggestedActions: ''),
    '1202': DlogAlarmReference(machine: 'reveos', code: '1202', name: 'Protocol problem', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'ProcedureFailureAlarm', occursDuring: 'A procedure.', detection: 'This alarm is raised when a time-out occurred before the end of a procedure substate.', possibleCauses: 'The protocol did not achieve the required substate end condition in the allotted time. Analyze the run data file to determine which action step timed out. Use STS to observe the device during a protocol and identify the failure.', suggestedActions: ''),
    '1203': DlogAlarmReference(machine: 'reveos', code: '1203', name: 'Protocol problem', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'ProcedureCRCFailureAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the device receives an invalid CRC for the configuration or protocol from the data system manager computer.', possibleCauses: 'One of the protocol files is corrupt. Overwrite the corrupt protocol file then check the data system manager. If the protocol is still corrupt, check the compact flash card. The version of this protocol is incompatible. Check the compatibility of the protocol version. The compact flash card is defective. Replace the compact flash card. Power cycle to clear the alarm', suggestedActions: ''),
    '1204': DlogAlarmReference(machine: 'reveos', code: '1204', name: 'Protocol problem', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'ProcedureLoadFailureAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the device fails to load the current procedure protocol from the compact flash card to the control computer.', possibleCauses: 'One of the files on the compact flash card is corrupt. Corruption typically occurs when the power is shut off while a protocol is being loaded. Disable the corrupt protocol in the data system manager. Reboot the device and select another protocol to overwrite the corrupt protocol. Use STS to upload a protocol and overwrite the corrupt file. Power cycle to clear the alarm The compact flash card is defective. Replace the compact flash card.', suggestedActions: ''),
    '1211': DlogAlarmReference(machine: 'reveos', code: '1211', name: 'Procedure not found', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'ConfigNotFoundAlarm', occursDuring: 'Startup.', detection: 'This alarm is raised when the device did not find a configuration file on the compact flash card during the startup state.', possibleCauses: 'The protocol loaded on the compact flash card is not enabled in STS. Accept the alarm then select an enabled protocol from the list. One of the files is corrupt. Re-enable the affected protocol in the data system manager. Use STS or the data system manager to transfer the correct protocol to the compact flash card.', suggestedActions: ''),
    '1212': DlogAlarmReference(machine: 'reveos', code: '1212', name: 'Device not enabled', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'DeviceDisabledAlarm', occursDuring: 'Always active.', detection: 'This alarm is raised when the device is disabled from the data system manager.', possibleCauses: 'The device is not enabled in the data system manager. Enable the device in the data system manager.', suggestedActions: ''),
    '1214': DlogAlarmReference(machine: 'reveos', code: '1214', name: 'No procedures assigned', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'DeviceHasNoConfigurations', occursDuring: 'At beginning if connected to the data system manager.', detection: 'This alarm is raised when the device has no configurations in config.dat.', possibleCauses: 'The device is unconfigured in the data system manager. Configure device in the data system manager.', suggestedActions: ''),
    '1219': DlogAlarmReference(machine: 'reveos', code: '1219', name: 'Hydraulic pressure too high', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'Bucket1HydOverPressureAlarm', occursDuring: 'Processing of that bucket.', detection: 'This alarm is raised when the hydraulic pressure sensor indicates the hydraulic pressure is 2.5 bar or greater.', possibleCauses: 'One of the bucket lines is kinked. Check the lines in the bucket for kinks. The frangible is unbroken or partially broken. Ensure that the frangible is properly broken. The hydraulic system has too much air. Purge air from the hydraulic system. The hydraulic pressure sensor connector is loose. Troubleshoot the hydraulic system for air and fluid leaks. The hydraulic pressure sensor is defective. Confirm the pressure sensor connector is secure. Compare hydraulic pressure sensor readings to a calibrated gauge. Replace the sensor if it is defective.', suggestedActions: ''),
