    '1263': DlogAlarmReference(machine: 'reveos', code: '1263', name: 'RBC detection problem', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'Bucket1BucketSensorRbcTriggerLateAlarm', occursDuring: 'Plasma expression (3C or 2C).', detection: 'This alarm is raised when the bucket interface sensor detects red blood cells too late.', possibleCauses: 'The label on the whole blood bag or some other object is preventing the bucket interface sensor from detecting the interface. Confirm the labels on the back of the whole blood bag do not interfere with the bucket sensors. The component bag set was not loaded correctly. Verify that the component bag set has been loaded correctly. The bucket interface sensor is dirty or defective. Clean the bucket interface sensor and check its operation.', suggestedActions: ''),
