    '1267': DlogAlarmReference(machine: 'reveos', code: '1267', name: 'Plasma detection problem', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'BulkExpressionFailureAlarm', occursDuring: 'Bulk Expression', detection: 'This alarm is raised when the line sensors do not properly detect the air/plasma interface during bulk expression.', possibleCauses: 'The component bag set was loaded incorrectly. Correctly load the tubing through the line sensor, valves, and guide channels. The plasma is lipemic. Check for lipemic plasma. The volume of whole blood is too low Check the draw volume. Avoid processing low volume units on more than one bucket. The line sensor is dirty. Clean the line sensor and check its operation.', suggestedActions: ''),
    '1268': DlogAlarmReference(machine: 'reveos', code: '1268', name: 'Hydraulic pressure too high--Obsolete', statusLine: '', messageType: '', dlogText: '', category: 'Procedure', alarmId: 'Bucket1HydOverPressureProtocolAlarm', occursDuring: 'This alarm is not used.', detection: 'Possible Cause Troubleshooting Actions N/A N/A', possibleCauses: 'N/A N/A', suggestedActions: ''),
