    'LeakDetectorT1LowVoltageFault': DlogAlarmReference(machine: 'optia', code: '', name: 'Voltage of fluid leak detector was below normal range.', statusLine: '', messageType: 'Control', dlogText: 'Fluid leak detector failed functionality test.', category: 'Control', alarmId: 'LeakDetectorT1LowVoltageFault', occursDuring: 'Power on', detection: 'The leak detector voltage is read as less than 2.0 V.', possibleCauses: 'l Intermittent connection on the Leak Detector CCA. l Defective Leak Detector CCA. l Defective leak detector.', suggestedActions: 'l Test the leak detector.'),
    'ControlCollectLineOcclusionAlarm': DlogAlarmReference(machine: 'optia', code: '', name: 'Volume in collection bag may be lower than reported.', statusLine: '', messageType: 'Control', dlogText: 'Tubing set did not contain expected amount of fluid. Check collection bag for appropriate volume.', category: 'Control', alarmId: 'ControlCollectLineOcclusionAlarm', occursDuring: 'Run mode', detection: 'The system detects that the reservoir volume error is more than 50% of the collected volume.', possibleCauses: 'l Defective valve occlusion. l Defective pump occlusion. l Defective Level Sensor. l I/O Two', suggestedActions: 'l Test the valve occlusion torque.'),
    'DatalogFailAlarm': DlogAlarmReference(machine: 'optia', code: '', name: 'Write-type communication error to data logging subsystem occurred.', statusLine: '', messageType: 'Control', dlogText: 'Data logging subsystem did not function correctly.', category: 'Control', alarmId: 'DatalogFailAlarm', occursDuring: 'Startup', detection: 'The Control system cannot write to the dlog.', possibleCauses: 'l Defective hard drive. l Defective control stack.', suggestedActions: 'l Replace the hard drive.'),
    'RBCDetectorWriteFault': DlogAlarmReference(machine: 'optia', code: '', name: 'Write-type communication error to RBC detector occurred.', statusLine: '', messageType: 'Control', dlogText: 'RBC detector did not function correctly.', category: 'Control', alarmId: 'RBCDetectorWriteFault', occursDuring: 'Continuously', detection: 'The RBC detector was unable to write to the dlog file.', possibleCauses: 'l Defective RBC detector. l Defective control stack.', suggestedActions: 'l Replace the RBC detector.'),
  };
  static DlogAlarmReference? lookup({required String machine, String? code, String? alarmName, String? dlogText}) {
    final m = machine.toLowerCase();
    if (m.contains('trima')) {
      final byCode = trimaByCode[(code ?? '').trim()]; if (byCode != null) return byCode;
      final q = _norm(dlogText?.isNotEmpty == true ? dlogText! : (alarmName ?? ''));
      if (q.isNotEmpty) for (final r in trimaByCode.values) { final d=_norm(r.dlogText); if (d.isNotEmpty && (q.contains(d) || d.contains(q))) return r; }
    }
    if (m.contains('reveos')) {
      final byCode = reveosByCode[(code ?? '').trim()]; if (byCode != null) return byCode;
      final q=_norm(alarmName ?? ''); if(q.isNotEmpty) for(final r in reveosByCode.values){ if(_norm(r.alarmId)==q) return r; }
    }
    if (m.contains('optia')) {
      final c=(code ?? '').trim(); if(optiaById.containsKey(c)) return optiaById[c];
      final q=_norm(alarmName ?? ''); if(q.isNotEmpty) for(final r in optiaById.values){ if(_norm(r.alarmId)==q || _norm(r.name)==q) return r; }
    }
    return null;
  }
  /// Resuelve por Alarm Identification (nombre técnico del manual).
  static DlogAlarmReference? byAlarmIdentification(String machine, String alarmIdentification) {
    final q = _norm(alarmIdentification);
    if (q.isEmpty) return null;
    final m = machine.toLowerCase();
    final values = m.contains('reveos') ? reveosByCode.values
        : m.contains('optia') ? optiaById.values
        : trimaByCode.values;
    for (final r in values) {
      if (_norm(r.alarmId) == q) return r;
    }
    return null;
  }

  /// Código oficial documentado. En Optia puede ser vacío porque el manual
  /// identifica la alarma por Alarm Identification y no por código numérico.
  static String officialCodeFor(String machine, String alarmIdentification) =>
      byAlarmIdentification(machine, alarmIdentification)?.code ?? '';

  static String? canonicalName({required String machine, String? code, String? rawName}) => lookup(machine:machine,code:code,alarmName:rawName,dlogText:rawName)?.name;
  static bool isKnown({required String machine, String? code, String? alarmName}) => lookup(machine:machine,code:code,alarmName:alarmName,dlogText:alarmName)!=null;
  static String? categoryForReveos(String code) => reveosByCode[code.trim()]?.category;
  static String? optiaKind(String id) => optiaById[id.trim()]?.category;
  static Map<String,String> get optiaKindById => {for(final e in optiaById.entries)e.key:e.value.category};
  static String _norm(String s) => s.toLowerCase().replaceAll(RegExp(r'^alarm\s+type\s*:\s*[a-z0-9]+\s*-\s*',caseSensitive:false),'').replaceAll(RegExp(r'[^a-z0-9]+'),' ').trim();
}
